export { LLMConfigProvider, useLLMConfig } from "./provider";
export { LLMConfigForm } from "./form";
export { ProviderSelector } from "./provider-selector";
export { AccessKeyInput } from "./access-key-input";
export { ModelSelector } from "./model-selector";
export { CollapsibleSection } from "./collapsible-section";
export { BaseUrlInput } from "./base-url-input";
export { TemperatureSlider } from "./temperature-slider";
export { ConnectionTestButton } from "./connection-test-button";

export type {
  LLMProvider,
  LLMModel,
  LLMConfig,
  ProviderConfig,
  ProviderField,
  ValidationResult,
  LLMConfigContextValue,
} from "./types";

export type { CollapsibleSectionProps } from "./collapsible-section";
export type { BaseUrlInputProps } from "./base-url-input";
export type { TemperatureSliderProps } from "./temperature-slider";
export type {
  TestResult,
  ConnectionTestButtonProps,
} from "./connection-test-button";

import type { ReactNode } from "react";

export type LLMProvider =
  | "openai"
  | "anthropic"
  | "azure-openai"
  | "google"
  | "cohere"
  | "ollama"
  | "custom";

export interface LLMModel {
  id: string;
  name: string;
  provider: LLMProvider;
  contextLength?: number;
  inputPrice?: number;
  outputPrice?: number;
}

export interface LLMConfig {
  provider: LLMProvider;
  apiKey: string;
  model: string;
  baseURL?: string;
  temperature?: number;
  maxTokens?: number;
  topP?: number;
  frequencyPenalty?: number;
  presencePenalty?: number;
  // Azure 特定
  azureDeploymentName?: string;
  azureApiVersion?: string;
  // 自定义字段
  customFields?: Record<string, any>;
}

export interface ProviderConfig {
  id: LLMProvider;
  name: string;
  displayName: string;
  icon?: ReactNode;
  baseURL?: string;
  apiVersion?: string;
  models: LLMModel[];
  fields?: ProviderField[];
}

export interface ProviderField {
  name: string;
  label: string;
  type: "text" | "password" | "select" | "number";
  required?: boolean;
  placeholder?: string;
  options?: { label: string; value: string }[];
  defaultValue?: any;
}

export type ValidationResult =
  | boolean
  | { valid: boolean; errors?: Record<string, string> };

export interface LLMConfigContextValue {
  config: LLMConfig;
  updateConfig: (config: Partial<LLMConfig>) => void;
  resetConfig: () => void;
  validateConfig: () => ValidationResult;
  getProviderConfig: () => ProviderConfig;
  getAvailableModels: () => LLMModel[];
}

"use client";

import { useLLMConfig } from "./provider";
import { cn } from "@/lib/utils";
import { Label } from "@/registry/new-york/ui/label";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/registry/new-york/ui/select";

export interface ModelSelectorProps {
  title?: string;
  groupByProvider?: boolean;
  filter?: (model: any) => boolean;
  error?: string;
  className?: string;
}

export function ModelSelector({
  title = "选择模型",
  filter,
  error,
  className,
}: ModelSelectorProps) {
  const { config, updateConfig, getAvailableModels } = useLLMConfig();
  const models = getAvailableModels().filter(filter || (() => true));

  return (
    <div className="space-y-2">
      {title && <Label>{title}</Label>}
      <Select
        value={config.model as string | undefined}
        onValueChange={(value) => updateConfig({ model: value })}
      >
        <SelectTrigger
          className={cn(
            error && "border-destructive focus-visible:ring-destructive",
            "w-full",
            className,
          )}
        >
          <SelectValue placeholder={title} />
        </SelectTrigger>
        <SelectContent>
          {models.map((model) => (
            <SelectItem key={model.id} value={String(model.id)}>
              {model.name}
            </SelectItem>
          ))}
        </SelectContent>
      </Select>
      {error && <p className="text-sm text-destructive">{error}</p>}
    </div>
  );
}

"use client";

import { useLLMConfig } from "./provider";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/registry/new-york/ui/select";
import { cn } from "@/lib/utils";
import { Label } from "@/registry/new-york/ui/label";
import type { LLMProvider } from "./types";

export interface ProviderSelectorProps {
  title?: string;
  className?: string;
}

export function ProviderSelector({
  title = "API 提供商",
  className,
}: ProviderSelectorProps) {
  const { config, updateConfig, getProviderConfig } = useLLMConfig();
  const providers = getProviderConfig()
    ? [getProviderConfig()]
    : [
        { id: "openai", displayName: "OpenAI" },
        { id: "anthropic", displayName: "Anthropic" },
        { id: "azure-openai", displayName: "Azure OpenAI" },
        { id: "google", displayName: "Google" },
        { id: "cohere", displayName: "Cohere" },
        { id: "ollama", displayName: "Ollama" },
      ];

  return (
    <div className={cn("space-y-2", className)}>
      {title && <Label>{title}</Label>}
      <Select
        value={config.provider}
        onValueChange={(value) =>
          updateConfig({ provider: value as LLMProvider })
        }
      >
        <SelectTrigger className="w-full">
          <SelectValue placeholder="选择提供商" />
        </SelectTrigger>
        <SelectContent>
          {providers.map((provider) => (
            <SelectItem key={provider.id} value={provider.id}>
              {provider.displayName}
            </SelectItem>
          ))}
        </SelectContent>
      </Select>
    </div>
  );
}

"use client";

import React, {
  createContext,
  useContext,
  useState,
  useCallback,
  useMemo,
} from "react";
import type {
  LLMConfig,
  ProviderConfig,
  ValidationResult,
  LLMConfigContextValue,
} from "./types";
import { DEFAULT_PROVIDERS, DEFAULT_CONFIG } from "@/lib/providers";

const LLMConfigContext = createContext<LLMConfigContextValue | undefined>(
  undefined,
);

export interface LLMConfigProviderProps {
  children: React.ReactNode;
  defaultConfig?: Partial<LLMConfig>;
  providers?: ProviderConfig[];
  onConfigChange?: (config: LLMConfig) => void;
  validate?: (config: LLMConfig) => ValidationResult;
}

export function LLMConfigProvider({
  children,
  defaultConfig,
  providers = DEFAULT_PROVIDERS,
  onConfigChange,
  validate,
}: LLMConfigProviderProps) {
  const [config, setConfig] = useState<LLMConfig>({
    ...DEFAULT_CONFIG,
    ...defaultConfig,
  });

  const updateConfig = useCallback(
    (newConfig: Partial<LLMConfig>) => {
      setConfig((prev) => {
        const updated = { ...prev, ...newConfig };
        onConfigChange?.(updated);
        return updated;
      });
    },
    [onConfigChange],
  );

  const resetConfig = useCallback(() => {
    setConfig({ ...DEFAULT_CONFIG, ...defaultConfig });
  }, [defaultConfig]);

  const validateConfig = useCallback((): ValidationResult => {
    if (validate) {
      return validate(config);
    }

    const errors: Record<string, string> = {};

    if (!config.provider) {
      errors.provider = "请选择提供商";
    }

    if (!config.apiKey) {
      errors.apiKey = "请输入 API Key";
    }

    if (!config.model) {
      errors.model = "请选择模型";
    }

    // 提供商特定验证
    if (config.provider === "azure-openai") {
      if (!config.azureDeploymentName) {
        errors.azureDeploymentName = "请输入部署名称";
      }
      if (!config.azureApiVersion) {
        errors.azureApiVersion = "请选择 API 版本";
      }
    }

    return Object.keys(errors).length === 0 ? true : { valid: false, errors };
  }, [config, validate]);

  const getProviderConfig = useCallback((): ProviderConfig => {
    return providers.find((p) => p.id === config.provider) || providers[0];
  }, [config.provider, providers]);

  const getAvailableModels = useCallback(() => {
    const provider = getProviderConfig();
    return provider.models;
  }, [getProviderConfig]);

  const value: LLMConfigContextValue = useMemo(
    () => ({
      config,
      updateConfig,
      resetConfig,
      validateConfig,
      getProviderConfig,
      getAvailableModels,
    }),
    [
      config,
      updateConfig,
      resetConfig,
      validateConfig,
      getProviderConfig,
      getAvailableModels,
    ],
  );

  return (
    <LLMConfigContext.Provider value={value}>
      {children}
    </LLMConfigContext.Provider>
  );
}

export function useLLMConfig() {
  const context = useContext(LLMConfigContext);
  if (context === undefined) {
    throw new Error("useLLMConfig must be used within a LLMConfigProvider");
  }
  return context;
}

"use client";

import React, { useState } from "react";
import { Button } from "@/registry/new-york/ui/button";
import { useLLMConfig } from "./provider";
import { cn } from "@/lib/utils";

export interface LLMConfigFormProps {
  children: React.ReactNode;
  onSubmit?: (config: any) => void | Promise<void>;
  onReset?: () => void;
  validateOnSubmit?: boolean;
  submitButtonText?: string;
  resetButtonText?: string;
  showSubmitButton?: boolean;
  showResetButton?: boolean;
  className?: string;
  progressive?: boolean; // 是否启用渐进式表单
}

export function LLMConfigForm({
  children,
  onSubmit,
  onReset,
  validateOnSubmit = true,
  submitButtonText = "保存",
  resetButtonText = "重置",
  showSubmitButton = true,
  showResetButton = true,
  className,
  progressive = false,
}: LLMConfigFormProps) {
  const { config, resetConfig, validateConfig } = useLLMConfig();
  const [errors, setErrors] = useState<Record<string, string>>({});

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();

    if (validateOnSubmit) {
      const result = validateConfig();
      if (result !== true) {
        setErrors((result as { errors?: Record<string, string> }).errors || {});
        return;
      }
    }

    setErrors({});
    await onSubmit?.(config);
  };

  const handleReset = () => {
    resetConfig();
    setErrors({});
    onReset?.();
  };

  // 渐进式表单逻辑：根据provider选择决定是否显示后续字段
  const shouldShowCredentials = !progressive || !!config.provider;

  return (
    <form onSubmit={handleSubmit} className={cn("space-y-6", className)}>
      <div className="space-y-4">
        {React.Children.map(children, (child) => {
          if (!React.isValidElement(child)) {
            return child;
          }

          const childType =
            (child.type as any).displayName || (child.type as any).name;
          const childProps = child.props as any;

          // 渐进式表单：ProviderSelector始终显示
          if (progressive && childType === "ProviderSelector") {
            return React.cloneElement(child as React.ReactElement<any>, {
              error: errors[childProps.name] || errors[childProps.fieldName],
            });
          }

          // 渐进式表单：其他组件只在provider选中后显示
          if (progressive && !shouldShowCredentials) {
            return null;
          }

          return React.cloneElement(child as React.ReactElement<any>, {
            error: errors[childProps.name] || errors[childProps.fieldName],
          });
        })}
      </div>

      {(showSubmitButton || showResetButton) && (
        <div className="flex justify-end gap-2">
          {showResetButton && (
            <Button type="button" variant="outline" onClick={handleReset}>
              {resetButtonText}
            </Button>
          )}
          {showSubmitButton && (
            <Button type="submit">{submitButtonText}</Button>
          )}
        </div>
      )}
    </form>
  );
}

"use client";

import React, { useState } from "react";
import { Button } from "@/registry/new-york/ui/button";
import { CheckCircle2, XCircle, Loader2 } from "lucide-react";
import { useLLMConfig } from "./provider";

export interface TestResult {
  success: boolean;
  data?: {
    provider: string;
    model: string;
    latency: number;
    usage?: any;
  };
  error?: string;
}

export interface ConnectionTestButtonProps {
  onSuccess?: (result: TestResult) => void;
  onError?: (error: string) => void;
  className?: string;
  children?: React.ReactNode;
}

export function ConnectionTestButton({
  onSuccess,
  onError,
  className,
  children = "测试连接",
}: ConnectionTestButtonProps) {
  const { config } = useLLMConfig();
  const [testing, setTesting] = useState(false);
  const [result, setResult] = useState<TestResult | null>(null);

  const handleTest = async () => {
    if (!config.provider || !config.apiKey) {
      onError?.("请先选择提供商并输入API Key");
      return;
    }

    setTesting(true);
    setResult(null);

    try {
      const response = await fetch("/api/test-connection", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
        },
        body: JSON.stringify({ config }),
      });

      const data = await response.json();
      setResult(data);

      if (data.success) {
        onSuccess?.(data);
      } else {
        onError?.(data.error || "连接测试失败");
      }
    } catch (error: any) {
      const errorResult: TestResult = {
        success: false,
        error: error.message || "网络请求失败",
      };
      setResult(errorResult);
      onError?.(error.message || "网络请求失败");
    } finally {
      setTesting(false);
    }
  };

  return (
    <div className={className}>
      <Button
        type="button"
        variant="outline"
        onClick={handleTest}
        disabled={testing || !config.provider || !config.apiKey}
        className="w-full"
      >
        {testing ? (
          <>
            <Loader2 className="mr-2 h-4 w-4 animate-spin" />
            测试中...
          </>
        ) : (
          children
        )}
      </Button>

      {result && (
        <div
          className={`mt-2 flex items-center gap-2 text-sm ${
            result.success ? "text-green-600" : "text-red-600"
          }`}
        >
          {result.success ? (
            <>
              <CheckCircle2 className="h-4 w-4" />
              <span>连接成功！延迟: {result.data?.latency}ms</span>
            </>
          ) : (
            <>
              <XCircle className="h-4 w-4" />
              <span>{result.error}</span>
            </>
          )}
        </div>
      )}
    </div>
  );
}

"use client";

import { useLLMConfig } from "./provider";
import { cn } from "@/lib/utils";
import { Label } from "@/registry/new-york/ui/label";

export interface TemperatureSliderProps {
  label?: string;
  min?: number;
  max?: number;
  step?: number;
  className?: string;
}

export function TemperatureSlider({
  label = "Temperature",
  min = 0,
  max = 2,
  step = 0.1,
  className,
}: TemperatureSliderProps) {
  const { config, updateConfig } = useLLMConfig();
  const temperature = config.temperature ?? 0.7;

  return (
    <div className={cn("space-y-2", className)}>
      <div className="flex items-center justify-between">
        {label && <Label>{label}</Label>}
        <span className="text-sm text-muted-foreground">{temperature}</span>
      </div>
      <input
        type="range"
        min={min}
        max={max}
        step={step}
        value={temperature}
        onChange={(e) =>
          updateConfig({ temperature: parseFloat(e.target.value) })
        }
        className="w-full h-2 bg-gray-200 rounded-lg appearance-none cursor-pointer accent-primary"
      />
    </div>
  );
}

"use client";

import React, { useState } from "react";
import { ChevronDown, ChevronRight } from "lucide-react";
import { cn } from "@/lib/utils";
import { Button } from "@/registry/new-york/ui/button";

export interface CollapsibleSectionProps {
  title: string;
  children: React.ReactNode;
  defaultOpen?: boolean;
  className?: string;
  contentClassName?: string;
}

export function CollapsibleSection({
  title,
  children,
  defaultOpen = false,
  className,
  contentClassName,
}: CollapsibleSectionProps) {
  const [isOpen, setIsOpen] = useState(defaultOpen);

  return (
    <div className={cn("border rounded-lg", className)}>
      <Button
        type="button"
        variant="ghost"
        className="w-full flex items-center justify-between px-4 py-3 h-auto hover:bg-muted/50"
        onClick={() => setIsOpen(!isOpen)}
      >
        <span className="font-medium">{title}</span>
        {isOpen ? (
          <ChevronDown className="h-4 w-4 transition-transform" />
        ) : (
          <ChevronRight className="h-4 w-4 transition-transform" />
        )}
      </Button>
      {isOpen && (
        <div className={cn("px-4 pb-4 pt-2 space-y-4", contentClassName)}>
          {children}
        </div>
      )}
    </div>
  );
}

"use client";

import { useLLMConfig } from "./provider";
import { cn } from "@/lib/utils";
import { Input } from "@/registry/new-york/ui/input";
import { Label } from "@/registry/new-york/ui/label";
import { Info } from "lucide-react";

export interface BaseUrlInputProps {
  label?: string;
  placeholder?: string;
  className?: string;
  error?: string;
}

export function BaseUrlInput({
  label = "Base URL",
  placeholder = "自定义 Base URL（可选）",
  className,
  error,
}: BaseUrlInputProps) {
  const { config, updateConfig, getProviderConfig } = useLLMConfig();
  const providerConfig = getProviderConfig();
  const defaultBaseUrl = providerConfig?.baseURL;

  return (
    <div className={cn("space-y-2", className)}>
      <div className="flex items-center gap-2">
        {label && <Label>{label}</Label>}
        {defaultBaseUrl && (
          <div className="flex items-center gap-1 text-xs text-muted-foreground">
            <Info className="h-3 w-3" />
            <span>默认: {defaultBaseUrl}</span>
          </div>
        )}
      </div>
      <Input
        type="url"
        placeholder={placeholder}
        value={config.baseURL || ""}
        onChange={(e) => updateConfig({ baseURL: e.target.value })}
        className={cn(
          error && "border-destructive focus-visible:ring-destructive",
        )}
      />
      {error && <p className="text-sm text-destructive">{error}</p>}
    </div>
  );
}

"use client";

import React, { useState } from "react";
import { Eye, EyeOff } from "lucide-react";
import { useLLMConfig } from "./provider";
import { cn } from "@/lib/utils";
import { Input } from "@/registry/new-york/ui/input";
import { Label } from "@/registry/new-york/ui/label";

export interface AccessKeyInputProps extends React.InputHTMLAttributes<HTMLInputElement> {
  label?: string;
  placeholder?: string;
  showToggle?: boolean;
  validate?: (value: string) => boolean | string;
  error?: string;
}

export function AccessKeyInput({
  label = "API Key",
  placeholder = "输入你的 API Key",
  showToggle = true,
  validate,
  error,
  className,
  ...props
}: AccessKeyInputProps) {
  const { config, updateConfig } = useLLMConfig();
  const [showPassword, setShowPassword] = useState(false);
  const [internalError, setInternalError] = useState<string | null>(null);

  const handleChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const value = e.target.value;
    updateConfig({ apiKey: value });

    if (validate) {
      const result = validate(value);
      setInternalError(typeof result === "string" ? result : null);
    }
  };

  const displayError = error || internalError;

  return (
    <div className="space-y-2">
      {label && <Label>{label}</Label>}
      <div className="relative">
        <Input
          type={showPassword ? "text" : "password"}
          className={cn(
            displayError && "border-destructive focus-visible:ring-destructive",
            className,
          )}
          placeholder={placeholder}
          value={config.apiKey}
          onChange={handleChange}
          {...props}
        />
        {showToggle && (
          <button
            type="button"
            onClick={() => setShowPassword(!showPassword)}
            className="absolute right-3 top-1/2 -translate-y-1/2 text-muted-foreground hover:text-foreground"
          >
            {showPassword ? (
              <EyeOff className="h-4 w-4" />
            ) : (
              <Eye className="h-4 w-4" />
            )}
          </button>
        )}
      </div>
      {displayError && (
        <p className="text-sm text-destructive">{displayError}</p>
      )}
    </div>
  );
}
